import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/lazyjp.html","title":"lazyjp","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.67,"words":202},"filePathRelative":"lazyjp.md"}`),a={name:`lazyjp.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="lazyjp" tabindex="-1"><a class="header-anchor" href="#lazyjp"><span>lazyjp</span></a></h1><p><a href="./技術的なメモ.html">技術的なメモ</a>, <a href="./VSCode.html">VSCode</a></p><p>ローマ字全部LLMに投げて変換するやつ、試してみようと思ったらVSCode拡張のlazyjpというのが一番ちゃんと使えそう。</p><p><a href="https://github.com/raspy135/lazyjp-vscode" target="_blank" rel="noopener noreferrer">raspy135/lazyjp-vscode</a></p><p>API Keyをセットすると書いてあるがそんなの持ってないのでGemmaで使いたい、と思ったら試したと言っている人が居るので出来るっぽい。 自分もやってみよう。</p><h2 id="ollamaのセットアップ" tabindex="-1"><a class="header-anchor" href="#ollamaのセットアップ"><span>ollamaのセットアップ</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ brew install ollama</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>サービスの立ち上げは以下らしい。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ brew services start ollama</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Gemma4 e2b(23億パラメータとか）を以下で試す。なお、120億パラメータはgemma4:12bらしい。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ollama run gemma4:e2b</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>7.2GBのダウンロードとか…</p><p>VSCode側ではCmd+pでlazyjpとするとSet API Keyというのがあるので、これを選んで<code>ollama</code>を入れるらしい。</p><p>settings.jsonに以下を書くらしい。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">  &quot;lazyjp.apiKey&quot;: &quot;ollama&quot;,</span>
<span class="line">  &quot;lazyjp.apiUrl&quot;: &quot;http://localhost:11434/v1&quot;,</span>
<span class="line">  &quot;lazyjp.model&quot;: &quot;gemma4:e2b&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これと同じになるように、Code＞Preferences＞Setttingsからlazyjpで検索してそれっぽいもので埋める。</p><h2 id="終わり方" tabindex="-1"><a class="header-anchor" href="#終わり方"><span>終わり方</span></a></h2><p>ollamaからの終わりは/exit</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&gt;&gt;&gt; /exit</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>あとは</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">brew services stop ollama</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>で良い。</p><h2 id="使ってみた感想、e2bでは全然駄目" tabindex="-1"><a class="header-anchor" href="#使ってみた感想、e2bでは全然駄目"><span>使ってみた感想、e2bでは全然駄目</span></a></h2><p>無事動いた。</p><p>ローマ字を入れてCmd+Alt+Jで行単位で変換出来るが、誤変換が多すぎてまったく使い物にならない。しかも遅すぎる。 e2bじゃ駄目だな。</p><h2 id="e4bで試した、全然違う日本語出す-2026-06-25-木" tabindex="-1"><a class="header-anchor" href="#e4bで試した、全然違う日本語出す-2026-06-25-木"><span>e4bで試した、全然違う日本語出す！ 2026-06-25 (木)</span></a></h2><p>e4bで試してみた所、入力したのと全く違う文を出す！</p><p>入力したのは以下。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">korehatesutodesu. nihonngogadounyuuryokudekikriunokatamesitemitaitoomoimasu.</span>
<span class="line">mecyaosoikedonanikahahyoujidekita.tadasikuugoiteirukana?</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>「これはテストです。日本語がどう入力できるのかためしてみたいと思います。」</li><li>「めっちゃ遅いけど何かは入力出来た。正しく動いているかな？」</li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">これテストです。日本語がどんな入出力できるか試してみたいと思います。</span>
<span class="line">めちゃくちゃに具合でも悪いのかな？大丈夫？</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div>`,31)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};